38	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point, pcb_t *pcb)
39	{
40	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
41	    pcb->kernel_sp -= sizeof(regs_context_t);
42	    /* initialization registers (ra, sp, gp) */
43	    pt_regs->regs[1] = entry_point;             //ra
44	    pt_regs->regs[2] = user_stack;              //sp
45	    pt_regs->regs[3] = (reg_t)__global_pointer$;//gp
46	}
